import"./chunk-VC46IEJQ.js";var e=(r,a)=>({en:r,zh:a}),o={group:"dorne",houses:[{id:"martell",names:e("House Martell","\u9A6C\u6CF0\u5C14\u5BB6\u65CF"),region:"dorne",seat:"sunspear",otherSeats:["water-gardens"],tier:"great",liege:null,sigil:e("A red sun pierced by a golden spear, on an orange field","\u6A59\u8272\u5E95\u4E0A\uFF0C\u4E00\u8F6E\u88AB\u91D1\u8272\u957F\u77DB\u8D2F\u7A7F\u7684\u7EA2\u65E5"),colors:["#e8782a","#c4232b"],words:e("Unbowed, Unbent, Unbroken","\u4E0D\u5C48\u4E0D\u6320\uFF0C\u4E0D\u6298\u4E0D\u4ECE"),summary:e("Princes of Dorne since Nymeria's Rhoynar married into the line of Lord Mors Martell a thousand years ago. Dorne alone kept its independence against Aegon's dragons and joined the realm only by marriage, so its rulers still style themselves princes, and Dornish law lets daughters inherit before younger sons.","\u81EA\u5343\u5E74\u524D\u5A1C\u6885\u8389\u4E9A\u7387\u6D1B\u4F0A\u62FF\u4EBA\u4E0E\u83AB\u65AF\xB7\u9A6C\u6CF0\u5C14\u5927\u4EBA\u8054\u59FB\u4EE5\u6765\uFF0C\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u4FBF\u662F\u591A\u6069\u7684\u4EB2\u738B\u3002\u591A\u6069\u662F\u552F\u4E00\u5728\u4F0A\u803F\u7684\u5DE8\u9F99\u9762\u524D\u4FDD\u4F4F\u72EC\u7ACB\u7684\u738B\u56FD\uFF0C\u6700\u7EC8\u9760\u8054\u59FB\u624D\u5E76\u5165\u738B\u571F\uFF0C\u56E0\u6B64\u5176\u7EDF\u6CBB\u8005\u81F3\u4ECA\u4ECD\u81EA\u79F0\u4EB2\u738B\uFF1B\u6309\u591A\u6069\u5F8B\u6CD5\uFF0C\u5973\u513F\u7684\u7EE7\u627F\u6743\u5148\u4E8E\u5E74\u5E7C\u7684\u513F\u5B50\u3002"),refs:["agot","asos","affc","adwd","twoiaf"],members:[{id:"princess-of-dorne-mother-of-doran",name:e("The Princess of Dorne (mother of Doran)","\u591A\u6069\u5973\u4EB2\u738B\uFF08\u9053\u6717\u4E4B\u6BCD\uFF09"),note:e("Ruling Princess of Dorne before Doran; her name is not given in the novels. She sought a Targaryen match for her children.","\u9053\u6717\u4E4B\u524D\u5728\u4F4D\u7684\u591A\u6069\u5973\u4EB2\u738B\uFF0C\u5C0F\u8BF4\u4E2D\u672A\u7ED9\u51FA\u5176\u540D\u3002\u5979\u66FE\u4E3A\u5B50\u5973\u8C0B\u6C42\u4E0E\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u8054\u59FB\u3002")},{id:"lewyn-martell",name:e("Lewyn Martell","\u9ECE\u6587\xB7\u9A6C\u6CF0\u5C14"),note:e("Brother of the Princess of Dorne; a knight of Aerys II's Kingsguard. Doran's uncle.","\u591A\u6069\u5973\u4EB2\u738B\u7684\u5F1F\u5F1F\uFF0C\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u5FA1\u6797\u94C1\u536B\u9A91\u58EB\uFF0C\u9053\u6717\u7684\u53D4\u8205\u3002"),fate:e("Fell at the Battle of the Trident fighting for Rhaegar.","\u5728\u4E09\u53C9\u621F\u6CB3\u4E4B\u6218\u4E2D\u4E3A\u96F7\u52A0\u4F5C\u6218\u9635\u4EA1\u3002")},{id:"doran-martell",name:e("Doran Martell","\u9053\u6717\xB7\u9A6C\u6CF0\u5C14"),mother:"princess-of-dorne-mother-of-doran",spouses:["mellario-of-norvos"],note:e("Prince of Dorne; patient, cautious and crippled by gout, he watches from the Water Gardens.","\u591A\u6069\u4EB2\u738B\uFF1B\u9690\u5FCD\u8C28\u614E\uFF0C\u9971\u53D7\u75DB\u98CE\u6298\u78E8\uFF0C\u5E38\u5728\u6D41\u6C34\u82B1\u56ED\u4E2D\u9759\u89C2\u65F6\u5C40\u3002"),fate:e("Reveals to Arianne a long-laid plan to avenge Elia: Quentyn was sent east to wed Daenerys Targaryen.","\u5411\u4E9A\u83B2\u6069\u63ED\u793A\u4E86\u4ED6\u4E3A\u4F0A\u8389\u4E9A\u590D\u4EC7\u7684\u957F\u8FDC\u8C0B\u5212\uFF1A\u6606\u5EF7\u88AB\u6D3E\u5F80\u4E1C\u65B9\uFF0C\u53BB\u8FCE\u5A36\u4E39\u59AE\u8389\u4E1D\xB7\u5766\u683C\u5229\u5B89\u3002")},{id:"mellario-of-norvos",name:e("Mellario of Norvos","\u8BFA\u4F5B\u65AF\u7684\u6885\u62C9\u91CC\u5965"),note:e("A Norvoshi noblewoman, Doran's wife; she returned to Norvos after quarrelling with him over fostering their son.","\u8BFA\u4F5B\u65AF\u8D35\u65CF\u5973\u5B50\uFF0C\u9053\u6717\u4E4B\u59BB\uFF1B\u56E0\u513F\u5B50\u7684\u5BC4\u517B\u95EE\u9898\u4E0E\u9053\u6717\u5931\u548C\uFF0C\u540E\u8FD4\u56DE\u8BFA\u4F5B\u65AF\u3002")},{id:"elia-martell",name:e("Elia Martell","\u4F0A\u8389\u4E9A\xB7\u9A6C\u6CF0\u5C14"),mother:"princess-of-dorne-mother-of-doran",spouses:["rhaegar-targaryen"],note:e("Princess of Dorne by birth, wife of Prince Rhaegar Targaryen and mother of Rhaenys and Aegon.","\u51FA\u8EAB\u591A\u6069\u7684\u516C\u4E3B\uFF0C\u96F7\u52A0\xB7\u5766\u683C\u5229\u5B89\u738B\u5B50\u4E4B\u59BB\uFF0C\u4F0A\u803F\u4E0E\u96F7\u59AE\u4E1D\u4E4B\u6BCD\u3002"),fate:e("Murdered with her children during the Sack of King's Landing; Dorne blames Gregor Clegane and Tywin Lannister.","\u5728\u541B\u4E34\u4E4B\u52AB\u4E2D\u4E0E\u5B69\u5B50\u4E00\u540C\u9047\u5BB3\uFF1B\u591A\u6069\u4EBA\u5C06\u6B64\u5F52\u7F6A\u4E8E\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u4E0E\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279\u3002")},{id:"oberyn-martell",name:e("Oberyn Martell","\u5965\u67CF\u4F26\xB7\u9A6C\u6CF0\u5C14"),mother:"princess-of-dorne-mother-of-doran",note:e("The Red Viper: Doran's younger brother, a feared fighter, poisoner and part-trained maester; father of eight bastard daughters, the Sand Snakes.",'"\u7EA2\u6BD2\u86C7"\uFF1A\u9053\u6717\u7684\u5F1F\u5F1F\uFF0C\u4EE4\u4EBA\u751F\u754F\u7684\u6B66\u58EB\u4E0E\u7528\u6BD2\u597D\u624B\uFF0C\u66FE\u5728\u5B66\u57CE\u4FEE\u4E60\uFF1B\u6709\u516B\u4E2A\u79C1\u751F\u5973\uFF0C\u4EBA\u79F0"\u6C99\u86C7"\u3002'),fate:e("Killed by Ser Gregor Clegane while championing Tyrion in his trial by combat.","\u5728\u4E3A\u63D0\u5229\u6602\u62C5\u4EFB\u51B3\u6597\u5BA1\u5224\u7684\u4EE3\u7406\u9A91\u58EB\u65F6\uFF0C\u88AB\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188\u7235\u58EB\u6740\u6B7B\u3002")},{id:"arianne-martell",name:e("Arianne Martell","\u4E9A\u83B2\u6069\xB7\u9A6C\u6CF0\u5C14"),father:"doran-martell",mother:"mellario-of-norvos",note:e("Doran's eldest child and heir under Dornish law; bold, sensual and frustrated by her father's caution.","\u9053\u6717\u7684\u957F\u5973\uFF0C\u6309\u591A\u6069\u5F8B\u6CD5\u4E3A\u7EE7\u627F\u4EBA\uFF1B\u5927\u80C6\u3001\u59A9\u5A9A\uFF0C\u5BF9\u7236\u4EB2\u7684\u754F\u7F29\u6DF1\u611F\u4E0D\u6EE1\u3002"),fate:e(`Plots to crown Myrcella Baratheon queen; the scheme fails and she is confined, then taken into her father's confidence and sent to meet "Young Griff".`,'\u5BC6\u8C0B\u62E5\u7ACB\u5F25\u8D5B\u83C8\xB7\u62DC\u62C9\u5E2D\u6069\u4E3A\u5973\u738B\uFF0C\u4E8B\u8D25\u540E\u906D\u8F6F\u7981\uFF1B\u5176\u540E\u5F97\u5230\u7236\u4EB2\u4FE1\u4EFB\uFF0C\u88AB\u6D3E\u53BB\u4F1A\u89C1"\u5C0F\u683C\u91CC\u82AC"\u3002')},{id:"quentyn-martell",name:e("Quentyn Martell","\u6606\u5EF7\xB7\u9A6C\u6CF0\u5C14"),father:"doran-martell",mother:"mellario-of-norvos",note:e("Doran's elder son, fostered at Yronwood; earnest and plain.","\u9053\u6717\u7684\u957F\u5B50\uFF0C\u5BC4\u517B\u4E8E\u94C1\u6728\u57CE\uFF1B\u8001\u5B9E\u8BDA\u6073\uFF0C\u76F8\u8C8C\u5E73\u5E73\u3002"),fate:e("Travels secretly to Meereen to woo Daenerys; dies of burns after trying to tame her dragons.","\u79D8\u5BC6\u524D\u5F80\u5F25\u6797\u5411\u4E39\u59AE\u8389\u4E1D\u6C42\u5A5A\uFF1B\u8BD5\u56FE\u9A6F\u670D\u5979\u7684\u9F99\uFF0C\u7ED3\u679C\u88AB\u70E7\u4F24\u81F4\u6B7B\u3002")},{id:"trystane-martell",name:e("Trystane Martell","\u5D14\u65AF\u4E39\xB7\u9A6C\u6CF0\u5C14"),father:"doran-martell",mother:"mellario-of-norvos",note:e("Doran's younger son, betrothed to Princess Myrcella Baratheon.","\u9053\u6717\u7684\u5E7C\u5B50\uFF0C\u4E0E\u5F25\u8D5B\u83C8\xB7\u62DC\u62C9\u5E2D\u6069\u516C\u4E3B\u8BA2\u6709\u5A5A\u7EA6\u3002")},{id:"obara-sand",name:e("Obara Sand","\u5965\u82AD\u5A05\xB7\u6C99\u5FB7"),father:"oberyn-martell",note:e("Eldest Sand Snake, daughter of an Oldtown whore; fierce, fights with a whip and spear.","\u6700\u5E74\u957F\u7684\u6C99\u86C7\uFF0C\u6BCD\u4EB2\u662F\u65E7\u9547\u7684\u5993\u5973\uFF1B\u6027\u60C5\u66B4\u70C8\uFF0C\u60EF\u7528\u957F\u97AD\u4E0E\u957F\u77DB\u3002")},{id:"nymeria-sand",name:e("Nymeria Sand","\u5A1C\u6885\u8389\u4E9A\xB7\u6C99\u5FB7"),father:"oberyn-martell",note:e('"Lady Nym", daughter of a Volantene noblewoman; elegant and deadly with hidden knives.','"\u5A1C\u59C6\u592B\u4EBA"\uFF0C\u6BCD\u4EB2\u662F\u74E6\u5170\u63D0\u65AF\u8D35\u65CF\u5973\u5B50\uFF1B\u4F18\u96C5\u800C\u81F4\u547D\uFF0C\u8EAB\u85CF\u98DE\u5200\u3002')},{id:"tyene-sand",name:e("Tyene Sand","\u6CF0\u59AE\u838E\xB7\u6C99\u5FB7"),father:"oberyn-martell",note:e("Daughter of a septa; golden-haired, sweet-seeming and a skilled poisoner.","\u6BCD\u4EB2\u662F\u4E00\u4F4D\u4FEE\u5973\uFF1B\u91D1\u53D1\u78A7\u773C\u3001\u5916\u8868\u751C\u7F8E\uFF0C\u5374\u662F\u7528\u6BD2\u9AD8\u624B\u3002")},{id:"sarella-sand",name:e("Sarella Sand","\u838E\u857E\u62C9\xB7\u6C99\u5FB7"),father:"oberyn-martell",note:e("Daughter of a Summer Islander ship's captain; said to have gone off travelling.","\u6BCD\u4EB2\u662F\u76DB\u590F\u7FA4\u5C9B\u7684\u4E00\u4F4D\u8239\u957F\uFF1B\u636E\u8BF4\u5916\u51FA\u6E38\u5386\u53BB\u4E86\u3002"),fate:e('Strongly hinted to be studying at the Citadel in disguise as the novice "Alleras".','\u4E66\u4E2D\u5F3A\u70C8\u6697\u793A\u5979\u5973\u626E\u7537\u88C5\uFF0C\u5316\u540D\u5B66\u5F92"\u963F\u52D2\u62C9\u65AF"\u5728\u5B66\u57CE\u6C42\u5B66\u3002'),spoiler:!1},{id:"elia-sand",name:e("Elia Sand","\u4F0A\u8389\u4E9A\xB7\u6C99\u5FB7"),father:"oberyn-martell",mother:"ellaria-sand",note:e("Eldest of Ellaria's daughters, fond of horses and the lance.","\u827E\u62C9\u8389\u4E9A\u6240\u751F\u7684\u957F\u5973\uFF0C\u559C\u7231\u9A91\u9A6C\u4E0E\u957F\u67AA\u3002")},{id:"obella-sand",name:e("Obella Sand","\u5965\u8D1D\u62C9\xB7\u6C99\u5FB7"),father:"oberyn-martell",mother:"ellaria-sand",note:e("Second of Ellaria's daughters.","\u827E\u62C9\u8389\u4E9A\u6240\u751F\u7684\u6B21\u5973\u3002")},{id:"dorea-sand",name:e("Dorea Sand","\u591A\u857E\u96C5\xB7\u6C99\u5FB7"),father:"oberyn-martell",mother:"ellaria-sand",note:e("Third of Ellaria's daughters.","\u827E\u62C9\u8389\u4E9A\u6240\u751F\u7684\u4E09\u5973\u3002")},{id:"loreza-sand",name:e("Loreza Sand","\u6D1B\u857E\u838E\xB7\u6C99\u5FB7"),father:"oberyn-martell",mother:"ellaria-sand",note:e("Youngest of Oberyn's daughters.","\u5965\u67CF\u4F26\u6700\u5C0F\u7684\u5973\u513F\u3002")}]},{id:"dayne",names:e("House Dayne of Starfall","\u661F\u5760\u57CE\u7684\u6234\u6069\u5BB6\u65CF"),region:"dorne",seat:"starfall",tier:"major",liege:"martell",sigil:e("A white sword and a falling star on a lilac field","\u6DE1\u7D2B\u8272\u5E95\u4E0A\uFF0C\u4E00\u67C4\u767D\u5251\u4E0E\u4E00\u9897\u5760\u661F"),colors:["#b7a2cf","#f4f2ee"],summary:e("One of the oldest houses of Westeros, of First Men descent, keepers of the ancestral sword Dawn. In each generation a Dayne judged worthy may carry it as the Sword of the Morning; the most famous was Ser Arthur Dayne of Aerys II's Kingsguard.",'\u7EF4\u65AF\u7279\u6D1B\u6700\u53E4\u8001\u7684\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u5148\u6C11\u540E\u88D4\uFF0C\u4E16\u4EE3\u5B88\u62A4\u7956\u4F20\u5B9D\u5251"\u9ECE\u660E"\u3002\u6BCF\u4E00\u4EE3\u4E2D\u88AB\u8BA4\u4E3A\u914D\u5F97\u4E0A\u7684\u6234\u6069\u5B50\u5F1F\u53EF\u6301\u6B64\u5251\uFF0C\u53F7\u79F0"\u62C2\u6653\u795E\u5251"\uFF1B\u5176\u4E2D\u6700\u8457\u540D\u7684\u662F\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u5FA1\u6797\u94C1\u536B\u4E9A\u745F\xB7\u6234\u6069\u7235\u58EB\u3002'),refs:["agot","asos","affc","twoiaf"],members:[{id:"lord-dayne-father-of-arthur",name:e("Lord of Starfall (father of Arthur and Ashara)","\u661F\u5760\u57CE\u4F2F\u7235\uFF08\u4E9A\u745F\u4E0E\u4E9A\u590F\u62C9\u4E4B\u7236\uFF09"),note:e("Not named in the novels.","\u5C0F\u8BF4\u4E2D\u672A\u7ED9\u51FA\u5176\u540D\u3002")},{id:"lord-dayne-father-of-edric",name:e("Lord of Starfall (father of Edric)","\u661F\u5760\u57CE\u4F2F\u7235\uFF08\u827E\u5FB7\u745E\u514B\u4E4B\u7236\uFF09"),father:"lord-dayne-father-of-arthur",note:e("Elder brother of Arthur, Ashara and Allyria; not named in the novels.","\u4E9A\u745F\u3001\u4E9A\u590F\u62C9\u4E0E\u7231\u8389\u5A05\u7684\u5144\u957F\uFF0C\u5C0F\u8BF4\u4E2D\u672A\u7ED9\u51FA\u5176\u540D\u3002")},{id:"arthur-dayne",name:e("Arthur Dayne","\u4E9A\u745F\xB7\u6234\u6069"),father:"lord-dayne-father-of-arthur",note:e("The Sword of the Morning, a knight of Aerys II's Kingsguard and close friend of Prince Rhaegar; widely held the finest knight of his age.",'"\u62C2\u6653\u795E\u5251"\uFF0C\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u5FA1\u6797\u94C1\u536B\uFF0C\u96F7\u52A0\u738B\u5B50\u7684\u631A\u53CB\uFF0C\u88AB\u666E\u904D\u89C6\u4E3A\u5F53\u4EE3\u6700\u6770\u51FA\u7684\u9A91\u58EB\u3002'),fate:e("Killed by Eddard Stark and Howland Reed at the tower of joy.","\u5728\u6781\u4E50\u5854\u88AB\u827E\u5FB7\xB7\u53F2\u5854\u514B\u4E0E\u970D\u5170\xB7\u9ECE\u5FB7\u6240\u6740\u3002")},{id:"ashara-dayne",name:e("Ashara Dayne","\u4E9A\u590F\u62C9\xB7\u6234\u6069"),father:"lord-dayne-father-of-arthur",note:e("Lady of Starfall's household, a lady-in-waiting to Elia Martell, remembered for her violet eyes.","\u661F\u5760\u57CE\u7684\u5C0F\u59D0\uFF0C\u66FE\u4EFB\u4F0A\u8389\u4E9A\xB7\u9A6C\u6CF0\u5C14\u7684\u4F8D\u5973\uFF0C\u4EE5\u4E00\u53CC\u7D2B\u7F57\u5170\u8272\u7684\u773C\u775B\u4E3A\u4EBA\u94ED\u8BB0\u3002"),fate:e("Said to have thrown herself from a tower at Starfall into the sea after the war, grieving a stillborn daughter.","\u636E\u8BF4\u6218\u540E\u56E0\u5973\u513F\u6B7B\u4EA7\u800C\u60B2\u6078\uFF0C\u4ECE\u661F\u5760\u57CE\u7684\u4E00\u5EA7\u5854\u4E0A\u6295\u6D77\u81EA\u5C3D\u3002")},{id:"allyria-dayne",name:e("Allyria Dayne","\u7231\u8389\u5A05\xB7\u6234\u6069"),father:"lord-dayne-father-of-arthur",note:e("Youngest sister of Arthur and Ashara, aunt of Edric; betrothed to Lord Beric Dondarrion.","\u4E9A\u745F\u4E0E\u4E9A\u590F\u62C9\u6700\u5C0F\u7684\u59B9\u59B9\uFF0C\u827E\u5FB7\u745E\u514B\u7684\u59D1\u6BCD\uFF1B\u4E0E\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069\u4F2F\u7235\u8BA2\u6709\u5A5A\u7EA6\u3002")},{id:"edric-dayne",name:e("Edric Dayne","\u827E\u5FB7\u745E\u514B\xB7\u6234\u6069"),father:"lord-dayne-father-of-edric",note:e(`Lord of Starfall as a boy, called "Ned"; squire to Beric Dondarrion and Arya Stark's companion in the brotherhood without banners.`,'\u5C11\u5E74\u661F\u5760\u57CE\u4F2F\u7235\uFF0C\u4EBA\u79F0"\u5948\u5FB7"\uFF1B\u8D1D\u91CC\xB7\u5510\u5FB7\u5229\u6069\u7684\u4F8D\u4ECE\uFF0C\u5728\u65E0\u65D7\u5144\u5F1F\u4F1A\u4E2D\u4E0E\u827E\u8389\u4E9A\xB7\u53F2\u5854\u514B\u7ED3\u4F34\u3002'),fate:e(`Tells Arya his wet nurse was "Wylla", whom he names as Jon Snow's mother.`,'\u544A\u8BC9\u827E\u8389\u4E9A\uFF0C\u4ED6\u7684\u5976\u5988"\u5A01\u62C9"\u6B63\u662F\u743C\u6069\xB7\u96EA\u8BFA\u7684\u6BCD\u4EB2\u3002')}]},{id:"dayne-of-high-hermitage",names:e("House Dayne of High Hermitage","\u9AD8\u9690\u5E90\u7684\u6234\u6069\u5BB6\u65CF"),region:"dorne",seat:"high-hermitage",tier:"minor",liege:"dayne",sigil:e("The Dayne sword and falling star, differenced for the cadet line (details not recalled)","\u6234\u6069\u5BB6\u65CF\u7684\u767D\u5251\u4E0E\u5760\u661F\uFF0C\u4EE5\u65C1\u652F\u65B9\u5F0F\u52A0\u4EE5\u533A\u522B\uFF08\u7EC6\u8282\u672A\u80FD\u786E\u8BA4\uFF09"),colors:["#8f7aa8","#f4f2ee"],summary:e(`A cadet branch of the Daynes holding the small castle of High Hermitage near Starfall. Its knight Ser Gerold Dayne, "Darkstar", resents being of the lesser line and is drawn into Arianne's plot.`,'\u6234\u6069\u5BB6\u65CF\u7684\u65C1\u652F\uFF0C\u636E\u5B88\u661F\u5760\u57CE\u9644\u8FD1\u7684\u5C0F\u57CE\u5821\u9AD8\u9690\u5E90\u3002\u5BB6\u65CF\u9A91\u58EB\u6770\u6D1B\xB7\u6234\u6069\u7235\u58EB\uFF0C\u4EBA\u79F0"\u6697\u661F"\uFF0C\u5BF9\u81EA\u5DF1\u8EAB\u4E3A\u65C1\u652F\u5FC3\u6000\u6028\u603C\uFF0C\u88AB\u5377\u5165\u4E86\u4E9A\u83B2\u6069\u7684\u5BC6\u8C0B\u3002'),refs:["affc"],members:[{id:"gerold-dayne",name:e("Gerold Dayne","\u6770\u6D1B\xB7\u6234\u6069"),note:e('"Darkstar", a cousin of the Starfall Daynes; silver hair with a black-purple streak, cold and dangerous.','"\u6697\u661F"\uFF0C\u661F\u5760\u57CE\u6234\u6069\u5BB6\u65CF\u7684\u8868\u4EB2\uFF1B\u94F6\u53D1\u4E2D\u5939\u7740\u4E00\u7F15\u7D2B\u9ED1\uFF0C\u51B7\u9177\u800C\u5371\u9669\u3002'),fate:e("Slashes Myrcella's face at the Greenblood and escapes into the mountains.","\u5728\u7EFF\u8840\u6CB3\u7554\u780D\u4F24\u5F25\u8D5B\u83C8\u7684\u8138\uFF0C\u968F\u540E\u9003\u5165\u5C71\u4E2D\u3002")}]},{id:"yronwood",names:e("House Yronwood","\u4F0A\u4F26\u4F0D\u5FB7\u5BB6\u65CF"),region:"dorne",seat:"yronwood",tier:"major",liege:"martell",sigil:e("A black portcullis on a bronze field","\u9752\u94DC\u8272\u5E95\u4E0A\uFF0C\u4E00\u9053\u9ED1\u8272\u95F8\u95E8"),colors:["#b0803c","#1d1b1a"],summary:e("An ancient First Men house that once ruled much of Dorne as kings and fought Nymeria's Martells before yielding. Its lords, who style themselves the Bloodroyal, command the strongest swords in Dorne and guard the Boneway. Prince Quentyn was fostered with them.",'\u53E4\u8001\u7684\u5148\u6C11\u5BB6\u65CF\uFF0C\u66FE\u4F5C\u4E3A\u56FD\u738B\u7EDF\u6CBB\u591A\u6069\u5927\u7247\u571F\u5730\uFF0C\u4E0E\u5A1C\u6885\u8389\u4E9A\u6276\u6301\u7684\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u4EA4\u6218\u540E\u624D\u4FEF\u9996\u79F0\u81E3\u3002\u5176\u9886\u4E3B\u81EA\u79F0"\u738B\u8840"\uFF0C\u9EBE\u4E0B\u5175\u529B\u4E3A\u591A\u6069\u6700\u5F3A\uFF0C\u627C\u5B88\u9AB8\u9AA8\u8DEF\u3002\u6606\u5EF7\u738B\u5B50\u66FE\u5BC4\u517B\u4E8E\u6B64\u3002'),refs:["affc","adwd","twoiaf"],members:[{id:"anders-yronwood",name:e("Anders Yronwood","\u5B89\u5FB7\u65AF\xB7\u4F0A\u4F26\u4F0D\u5FB7"),note:e("Lord of Yronwood, the Bloodroyal, Warden of the Stone Way; Quentyn's foster-father and no friend of the Martells.",'\u94C1\u6728\u57CE\u4F2F\u7235\uFF0C"\u738B\u8840"\uFF0C\u77F3\u8DEF\u5B88\u62A4\uFF1B\u6606\u5EF7\u7684\u517B\u7236\uFF0C\u4E0E\u9A6C\u6CF0\u5C14\u5BB6\u65CF\u7D20\u4E0D\u4EB2\u8FD1\u3002')},{id:"ynys-yronwood",name:e("Ynys Yronwood","\u4F0A\u59AE\u4E1D\xB7\u4F0A\u4F26\u4F0D\u5FB7"),father:"anders-yronwood",spouses:["ryon-allyrion"],note:e("Lord Anders's eldest daughter, married to Ser Ryon Allyrion.","\u5B89\u5FB7\u65AF\u5927\u4EBA\u7684\u957F\u5973\uFF0C\u5AC1\u7ED9\u83B1\u6069\xB7\u827E\u5229\u6602\u7235\u58EB\u3002")},{id:"cletus-yronwood",name:e("Cletus Yronwood","\u514B\u83B1\u7279\u65AF\xB7\u4F0A\u4F26\u4F0D\u5FB7"),father:"anders-yronwood",note:e("Lord Anders's son and heir; a friend of Arianne who joins her plot to crown Myrcella.","\u5B89\u5FB7\u65AF\u5927\u4EBA\u7684\u513F\u5B50\u4E0E\u7EE7\u627F\u4EBA\uFF1B\u4E9A\u83B2\u6069\u7684\u670B\u53CB\uFF0C\u53C2\u4E0E\u4E86\u62E5\u7ACB\u5F25\u8D5B\u83C8\u7684\u5BC6\u8C0B\u3002")},{id:"gwyneth-yronwood",name:e("Gwyneth Yronwood","\u845B\u6E29\u59AE\u4E1D\xB7\u4F0A\u4F26\u4F0D\u5FB7"),father:"anders-yronwood",note:e("Lord Anders's youngest daughter.","\u5B89\u5FB7\u65AF\u5927\u4EBA\u7684\u5E7C\u5973\u3002")},{id:"archibald-yronwood",name:e("Archibald Yronwood","\u963F\u5947\u5DF4\u5FB7\xB7\u4F0A\u4F26\u4F0D\u5FB7"),note:e(`"The Big Man", a huge, good-natured kinsman of Lord Anders (his exact parentage is uncertain here); Quentyn's companion on the journey east.`,'"\u5927\u4E2A\u5B50"\uFF0C\u5B89\u5FB7\u65AF\u5927\u4EBA\u8EAB\u6750\u9B41\u68A7\u3001\u6027\u60C5\u61A8\u539A\u7684\u4EB2\u65CF\uFF08\u786E\u5207\u4EB2\u7F18\u6B64\u5904\u4E0D\u786E\u5B9A\uFF09\uFF1B\u966A\u6606\u5EF7\u4E1C\u884C\u7684\u540C\u4F34\u3002')}]},{id:"allyrion",names:e("House Allyrion","\u827E\u5229\u6602\u5BB6\u65CF"),region:"dorne",seat:"godsgrace",tier:"major",liege:"martell",sigil:e("A gold hand on a red-and-gold field (as usually described; not certain)","\u7EA2\u91D1\u76F8\u95F4\u7684\u5E95\u4E0A\uFF0C\u4E00\u53EA\u91D1\u8272\u624B\u638C\uFF08\u5E38\u89C1\u63CF\u8FF0\uFF0C\u4E0D\u786E\u5B9A\uFF09"),colors:["#b4262c","#d9b13b"],summary:e("Lords of Godsgrace at the head of the Greenblood, one of the richest river valleys in Dorne. Lady Delonne Allyrion rules there; her son Ser Ryon is married to a Yronwood, and the Bastard of Godsgrace, Ser Daemon Sand, was Oberyn's squire.",'\u795E\u6069\u57CE\u9886\u4E3B\uFF0C\u5750\u62E5\u7EFF\u8840\u6CB3\u6E90\u5934\u2014\u2014\u591A\u6069\u6700\u5BCC\u9976\u7684\u6CB3\u8C37\u4E4B\u4E00\u3002\u8FEA\u6D1B\u59AE\xB7\u827E\u5229\u6602\u592B\u4EBA\u7EDF\u6CBB\u6B64\u5730\uFF1B\u5979\u7684\u513F\u5B50\u83B1\u6069\u7235\u58EB\u5A36\u4E86\u4F0A\u4F26\u4F0D\u5FB7\u5BB6\u7684\u5973\u513F\uFF0C"\u795E\u6069\u57CE\u7684\u79C1\u751F\u5B50"\u6234\u8499\xB7\u6C99\u5FB7\u7235\u58EB\u66FE\u662F\u5965\u67CF\u4F26\u7684\u4F8D\u4ECE\u3002'),refs:["affc","twoiaf"],members:[{id:"delonne-allyrion",name:e("Delonne Allyrion","\u8FEA\u6D1B\u59AE\xB7\u827E\u5229\u6602"),note:e("Lady of Godsgrace.","\u795E\u6069\u57CE\u5973\u4F2F\u7235\u3002")},{id:"ryon-allyrion",name:e("Ryon Allyrion","\u83B1\u6069\xB7\u827E\u5229\u6602"),mother:"delonne-allyrion",note:e("Heir to Godsgrace; husband of Ynys Yronwood.","\u795E\u6069\u57CE\u7EE7\u627F\u4EBA\uFF0C\u4F0A\u59AE\u4E1D\xB7\u4F0A\u4F26\u4F0D\u5FB7\u7684\u4E08\u592B\u3002")},{id:"daemon-sand",name:e("Daemon Sand","\u6234\u8499\xB7\u6C99\u5FB7"),note:e("The Bastard of Godsgrace, once Oberyn's squire; he asked for Arianne's hand and was refused by Doran.",'"\u795E\u6069\u57CE\u7684\u79C1\u751F\u5B50"\uFF0C\u66FE\u4EFB\u5965\u67CF\u4F26\u7684\u4F8D\u4ECE\uFF1B\u4ED6\u66FE\u5411\u4E9A\u83B2\u6069\u6C42\u5A5A\uFF0C\u88AB\u9053\u6717\u62D2\u7EDD\u3002')}]},{id:"uller",names:e("House Uller","\u4E4C\u52D2\u5BB6\u65CF"),region:"dorne",seat:"hellholt",tier:"major",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#6b1d1d","#e0b84a"],summary:e("Lords of the Hellholt on the Brimstone, a house with a reputation for wild blood and madness. Lord Harmen Uller's natural daughter Ellaria Sand became Prince Oberyn's paramour.","\u786B\u78FA\u6CB3\u7554\u5730\u72F1\u5821\u7684\u9886\u4E3B\uFF0C\u8FD9\u4E2A\u5BB6\u65CF\u7D20\u6709\u8840\u6027\u72C2\u91CE\u3001\u6613\u751F\u75AF\u766B\u4E4B\u540D\u3002\u54C8\u8499\xB7\u4E4C\u52D2\u5927\u4EBA\u7684\u79C1\u751F\u5973\u827E\u62C9\u8389\u4E9A\xB7\u6C99\u5FB7\u6210\u4E86\u5965\u67CF\u4F26\u4EB2\u738B\u7684\u60C5\u4EBA\u3002"),refs:["asos","affc","twoiaf"],members:[{id:"harmen-uller",name:e("Harmen Uller","\u54C8\u8499\xB7\u4E4C\u52D2"),note:e("Lord of the Hellholt; father of Ellaria Sand.","\u5730\u72F1\u5821\u4F2F\u7235\uFF0C\u827E\u62C9\u8389\u4E9A\xB7\u6C99\u5FB7\u4E4B\u7236\u3002")},{id:"ellaria-sand",name:e("Ellaria Sand","\u827E\u62C9\u8389\u4E9A\xB7\u6C99\u5FB7"),father:"harmen-uller",note:e("Natural daughter of Lord Harmen Uller of Hellholt; Oberyn's paramour and mother of his four youngest daughters.","\u5730\u72F1\u5821\u54C8\u8499\xB7\u4E4C\u52D2\u5927\u4EBA\u7684\u79C1\u751F\u5973\uFF1B\u5965\u67CF\u4F26\u7684\u60C5\u4EBA\uFF0C\u4ED6\u6700\u5C0F\u7684\u56DB\u4E2A\u5973\u513F\u4E4B\u6BCD\u3002")},{id:"ulwyck-uller",name:e("Ulwyck Uller","\u4E4C\u5A01\u514B\xB7\u4E4C\u52D2"),note:e("A knight of the house, kinsman of Lord Harmen (relation not certain here).","\u5BB6\u65CF\u9A91\u58EB\uFF0C\u54C8\u8499\u5927\u4EBA\u7684\u4EB2\u65CF\uFF08\u5177\u4F53\u5173\u7CFB\u6B64\u5904\u4E0D\u786E\u5B9A\uFF09\u3002")}]},{id:"qorgyle",names:e("House Qorgyle","\u79D1\u683C\u5C14\u5BB6\u65CF"),region:"dorne",seat:"sandstone",tier:"minor",liege:"martell",sigil:e("Three black scorpions on a red field","\u7EA2\u5E95\u4E0A\u4E09\u53EA\u9ED1\u874E"),colors:["#b3261e","#141414"],summary:e("Lords of Sandstone in the western deep sands. Ser Gulian Qorgyle was one of the Dornish knights who rode with Prince Oberyn to King's Landing.","\u897F\u90E8\u6DF1\u6C99\u4E2D\u6C99\u77F3\u57CE\u7684\u9886\u4E3B\u3002\u53E4\u91CC\u5B89\xB7\u79D1\u683C\u5C14\u7235\u58EB\u662F\u968F\u5965\u67CF\u4F26\u4EB2\u738B\u524D\u5F80\u541B\u4E34\u7684\u591A\u6069\u9A91\u58EB\u4E4B\u4E00\u3002"),refs:["asos","twoiaf"]},{id:"fowler",names:e("House Fowler","\u4F5B\u52D2\u5BB6\u65CF"),region:"dorne",seat:"skyreach",tier:"major",liege:"martell",sigil:e("A falcon soaring, on a field divided green and yellow","\u7EFF\u9EC4\u5BF9\u5206\u7684\u5E95\u4E0A\uFF0C\u4E00\u53EA\u7FF1\u7FD4\u7684\u730E\u9E70"),colors:["#2f7a3d","#e4c13b"],words:e("Let Me Soar","\u8BA9\u6211\u7FF1\u7FD4"),summary:e("Lords of Skyreach, guardians of the Prince's Pass. Their lands are the first that armies from the Reach must take, and the Fowler twins Jeyne and Jennelyn are known for their skill in arms.","\u5929\u53CA\u57CE\u9886\u4E3B\uFF0C\u4EB2\u738B\u9698\u53E3\u7684\u5B88\u62A4\u8005\u3002\u81EA\u6CB3\u6E7E\u5730\u6765\u72AF\u7684\u5927\u519B\u5FC5\u5148\u653B\u53D6\u4ED6\u4EEC\u7684\u9886\u5730\uFF1B\u4F5B\u52D2\u5BB6\u7684\u53CC\u80DE\u80CE\u59D0\u59B9\u73CD\u59AE\u4E0E\u73CD\u59AE\u6797\u4EE5\u6B66\u827A\u95FB\u540D\u3002"),refs:["asos","affc","twoiaf"]},{id:"manwoody",names:e("House Manwoody","\u66FC\u4F0D\u8FEA\u5BB6\u65CF"),region:"dorne",seat:"kingsgrave",tier:"major",liege:"martell",sigil:e("A crowned skull on black","\u9ED1\u5E95\u4E0A\u4E00\u9897\u6234\u51A0\u9AB7\u9AC5"),colors:["#151515","#e9e4d8"],summary:e("Lords of Kingsgrave in the Red Mountains. Lord Dagos Manwoody, a steady supporter of Sunspear, has sons named Mors and Dickon and a brother, Ser Myles.","\u8D64\u7EA2\u5C71\u8109\u4E2D\u738B\u5893\u7684\u9886\u4E3B\u3002\u8FBE\u6208\u65AF\xB7\u66FC\u4F0D\u8FEA\u5927\u4EBA\u4E00\u5411\u652F\u6301\u9633\u621F\u57CE\uFF0C\u819D\u4E0B\u6709\u83AB\u65AF\u4E0E\u72C4\u80AF\u4E8C\u5B50\uFF0C\u53E6\u6709\u4E00\u5F1F\u8FC8\u5C14\u65AF\u7235\u58EB\u3002"),refs:["affc","twoiaf"]},{id:"blackmont",names:e("House Blackmont","\u5E03\u83B1\u514B\u8499\u5BB6\u65CF"),region:"dorne",seat:"blackmont",tier:"minor",liege:"martell",sigil:e("A black vulture grasping a babe in its claws, on orange","\u6A59\u5E95\u4E0A\u4E00\u53EA\u722A\u652B\u5A74\u5B69\u7684\u9ED1\u79C3\u9E6B"),colors:["#e07a2a","#151515"],summary:e("Lords of Blackmont in the Red Mountains. Lady Larra Blackmont, her daughter Jynessa and son Perros came to King's Landing in Prince Oberyn's train.","\u8D64\u7EA2\u5C71\u8109\u4E2D\u9ED1\u5C71\u57CE\u7684\u9886\u4E3B\u3002\u62C9\u62C9\xB7\u5E03\u83B1\u514B\u8499\u592B\u4EBA\u643A\u5973\u513F\u5409\u59AE\u838E\u4E0E\u513F\u5B50\u6D3E\u6D1B\u65AF\uFF0C\u968F\u5965\u67CF\u4F26\u4EB2\u738B\u4E00\u884C\u6765\u5230\u541B\u4E34\u3002"),refs:["asos","twoiaf"]},{id:"wyl",names:e("House Wyl","\u5A01\u5C14\u5BB6\u65CF"),region:"dorne",seat:"wyl",tier:"minor",liege:"yronwood",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#3a3a2f","#c4a65a"],summary:e("Lords of Wyl on the Boneway, sworn to Yronwood (the liege link is an assumption here). Stormlanders long remembered them for cruelty to captives taken in the mountains.","\u9AB8\u9AA8\u8DEF\u4E0A\u5A01\u5C14\u57CE\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u4F0A\u4F26\u4F0D\u5FB7\u5BB6\u65CF\uFF08\u6B64\u5C01\u81E3\u5173\u7CFB\u4E3A\u672C\u56FE\u63A8\u6D4B\uFF09\u3002\u98CE\u66B4\u5730\u4EBA\u957F\u4E45\u8BB0\u5F97\u4ED6\u4EEC\u5BF9\u5C71\u4E2D\u4FD8\u864F\u7684\u6B8B\u5FCD\u3002"),refs:["twoiaf"]},{id:"gargalen",names:e("House Gargalen","\u76D6\u52A0\u4F26\u5BB6\u65CF"),region:"dorne",seat:"salt-shore",tier:"minor",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#c75b2a","#f2e6c8"],summary:e("Lords of Salt Shore on the Summer Sea coast. Lord Tremond Gargalen is among the Dornish lords at Sunspear in A Feast for Crows.","\u590F\u65E5\u4E4B\u6D77\u6CBF\u5CB8\u76D0\u6EE8\u57CE\u7684\u9886\u4E3B\u3002\u5728\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u7279\u8499\u5FB7\xB7\u76D6\u52A0\u4F26\u5927\u4EBA\u662F\u805A\u96C6\u5728\u9633\u621F\u57CE\u7684\u591A\u6069\u9886\u4E3B\u4E4B\u4E00\u3002"),refs:["affc","twoiaf"]},{id:"toland",names:e("House Toland","\u6258\u5170\u5BB6\u65CF"),region:"dorne",seat:"ghost-hill",tier:"minor",liege:"martell",sigil:e("A green dragon biting its own tail, on gold","\u91D1\u5E95\u4E0A\u4E00\u6761\u54AC\u4F4F\u81EA\u5DF1\u5C3E\u5DF4\u7684\u7EFF\u9F99"),colors:["#d8b23c","#2f6e3a"],summary:e("Lords of Ghost Hill. Lady Nymella Toland is one of the Dornish nobles present at Sunspear in A Feast for Crows.","\u9B3C\u4E18\u57CE\u7684\u9886\u4E3B\u3002\u5728\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\uFF0C\u59AE\u6885\u62C9\xB7\u6258\u5170\u592B\u4EBA\u662F\u8EAB\u5728\u9633\u621F\u57CE\u7684\u591A\u6069\u8D35\u65CF\u4E4B\u4E00\u3002"),refs:["affc","twoiaf"]},{id:"vaith",names:e("House Vaith","\u7EF4\u65AF\u5BB6\u65CF"),region:"dorne",seat:"vaith",tier:"minor",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#c9a25a","#3d2a1a"],summary:e("Lords of Vaith in the deep sands, sworn to Sunspear. Little else about them is told in the novels.","\u6DF1\u6C99\u4E2D\u7EF4\u65AF\u57CE\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u9633\u621F\u57CE\u3002\u5C0F\u8BF4\u4E2D\u5173\u4E8E\u4ED6\u4EEC\u7684\u8BB0\u8FF0\u5BE5\u5BE5\u3002"),refs:["affc","twoiaf"]},{id:"jordayne",names:e("House Jordayne","\u4E54\u6234\u6069\u5BB6\u65CF"),region:"dorne",seat:"tor",tier:"minor",liege:"martell",sigil:e("A golden quill on a green field","\u7EFF\u5E95\u4E0A\u4E00\u652F\u91D1\u8272\u7FBD\u6BDB\u7B14"),colors:["#2f6b3a","#e2bd4a"],summary:e("Lords of the Tor in south-western Dorne. Myria Jordayne, heir to the Tor, is mentioned among Arianne's acquaintances.","\u591A\u6069\u897F\u5357\u90E8\u6258\u5C14\u57CE\u7684\u9886\u4E3B\u3002\u6258\u5C14\u57CE\u7EE7\u627F\u4EBA\u7C73\u8389\u4E9A\xB7\u4E54\u6234\u6069\u5728\u4E66\u4E2D\u88AB\u63D0\u53CA\u4E3A\u4E9A\u83B2\u6069\u7684\u65E7\u8BC6\u3002"),refs:["affc","twoiaf"]},{id:"dalt",names:e("House Dalt","\u6234\u5C14\u7279\u5BB6\u65CF"),region:"dorne",seat:"lemonwood",tier:"minor",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#2b4f8a","#f0d64a"],summary:e(`Lords of Lemonwood near Sunspear. Ser Andrey "Drey" Dalt, the heir, joins Arianne's attempt to crown Myrcella.`,'\u9633\u621F\u57CE\u9644\u8FD1\u67E0\u6AAC\u6797\u57CE\u7684\u9886\u4E3B\u3002\u7EE7\u627F\u4EBA\u5B89\u5FB7\u96F7\uFF08"\u5FB7\u96F7"\uFF09\xB7\u6234\u5C14\u7279\u7235\u58EB\u53C2\u4E0E\u4E86\u4E9A\u83B2\u6069\u62E5\u7ACB\u5F25\u8D5B\u83C8\u7684\u884C\u52A8\u3002'),refs:["affc"],members:[{id:"andrey-dalt",name:e("Andrey Dalt","\u5B89\u5FB7\u96F7\xB7\u6234\u5C14\u7279"),note:e(`"Drey", heir to Lemonwood and Arianne's childhood friend.`,'"\u5FB7\u96F7"\uFF0C\u67E0\u6AAC\u6797\u57CE\u7EE7\u627F\u4EBA\uFF0C\u4E9A\u83B2\u6069\u7684\u7AE5\u5E74\u597D\u53CB\u3002'),fate:e("After the plot fails he is sent to Norvos to serve Arianne's mother.","\u5BC6\u8C0B\u5931\u8D25\u540E\uFF0C\u4ED6\u88AB\u9063\u5F80\u8BFA\u4F5B\u65AF\u4F8D\u5949\u4E9A\u83B2\u6069\u7684\u6BCD\u4EB2\u3002")}]},{id:"santagar",names:e("House Santagar","\u6851\u5854\u52A0\u5BB6\u65CF"),region:"dorne",seat:"spottswood",tier:"minor",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#3c6b4a","#e6dcc0"],summary:e(`Lords of Spottswood. Their heir, Sylva Santagar \u2014 "Spotted Sylva" for her freckles \u2014 is one of Arianne's companions.`,'\u6591\u6797\u57CE\u7684\u9886\u4E3B\u3002\u5BB6\u65CF\u7EE7\u627F\u4EBA\u5E2D\u5C14\u5A03\xB7\u6851\u5854\u52A0\u56E0\u6EE1\u8138\u96C0\u6591\u800C\u88AB\u79F0\u4F5C"\u6591\u70B9\u5E2D\u5C14\u5A03"\uFF0C\u662F\u4E9A\u83B2\u6069\u7684\u540C\u4F34\u4E4B\u4E00\u3002'),refs:["affc"],members:[{id:"sylva-santagar",name:e("Sylva Santagar","\u5E2D\u5C14\u5A03\xB7\u6851\u5854\u52A0"),note:e('"Spotted Sylva", heir to Spottswood.','"\u6591\u70B9\u5E2D\u5C14\u5A03"\uFF0C\u6591\u6797\u57CE\u7EE7\u627F\u4EBA\u3002'),fate:e("After the plot fails she is married off to old Lord Eldon Estermont.","\u5BC6\u8C0B\u5931\u8D25\u540E\uFF0C\u5979\u88AB\u8BB8\u914D\u7ED9\u5E74\u8FC8\u7684\u827E\u5C14\u987F\xB7\u827E\u65AF\u7279\u8499\u4F2F\u7235\u3002")}]},{id:"drinkwater",names:e("House Drinkwater","\u5FB7\u6797\u514B\u6C83\u7279\u5BB6\u65CF"),region:"dorne",tier:"minor",liege:"martell",sigil:e("Arms not described with certainty in the sources consulted","\u6240\u67E5\u8D44\u6599\u4E2D\u672A\u80FD\u786E\u8BA4\u5176\u7EB9\u7AE0"),colors:["#2a5f86","#e8e2cf"],summary:e("A Dornish knightly house whose seat is not named in the novels. Ser Gerris Drinkwater, quick-witted and charming, travels east with Prince Quentyn.","\u591A\u6069\u7684\u9A91\u58EB\u5BB6\u65CF\uFF0C\u5C0F\u8BF4\u672A\u63D0\u53CA\u5176\u5C45\u57CE\u3002\u673A\u654F\u98CE\u8DA3\u7684\u845B\u5229\u65AF\xB7\u5FB7\u6797\u514B\u6C83\u7279\u7235\u58EB\u966A\u540C\u6606\u5EF7\u738B\u5B50\u4E1C\u884C\u3002"),refs:["adwd"],members:[{id:"gerris-drinkwater",name:e("Gerris Drinkwater","\u845B\u5229\u65AF\xB7\u5FB7\u6797\u514B\u6C83\u7279"),note:e("Quentyn's friend and companion on the voyage to Meereen.","\u6606\u5EF7\u7684\u670B\u53CB\uFF0C\u968F\u4ED6\u8FDC\u8D74\u5F25\u6797\u7684\u540C\u4F34\u3002")}]}]};export{o as default};
